def _double_failure_tree_path() -> Path:
    """Return a fresh fixed-named leaf inside a new system temporary parent.

    The parent is a real ``mkdtemp`` directory (a direct child of the
    system temporary root, removed by the caller's safety net), while the
    leaf itself always carries the same name so the simulated removal error
    names the real directory yet stays byte-stable run after run.
    """
    return Path(tempfile.mkdtemp(prefix="teardown-double-failure-")) / (
        _DOUBLE_FAILURE_TREE_NAME
    )

